mapper.select:

  SELECT c.*, '' AS agent_name FROM agent_conversation c
  
    
  

WHERE c.enterprise_id = #{enterprise} AND c.user_id = #{user} AND c.id = #{id}
FOR UPDATE


WHERE c.enterprise_id = #{enterprise} AND c.user_id = #{user} AND c.status = #{status} AND c.mode = 'normal'
AND c.favorite = #{favorite}
AND c.agent_id = #{agentId}
AND LOCATE(#{query}, c.title) > 0
AND c.deleted_at > #{oldestDeleted}

  AND (c.updated_at < #{after.time} OR (c.updated_at = #{after.time} AND c.id < #{after.id}))

ORDER BY c.updated_at DESC, c.id DESC LIMIT #{limit}
